const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=null, profiles=[],tab='overview',adminCache={},siteConfig={services:[],locations:[]},vipInfo={status:'none',expires_at:null},savedIds=new Set();
async function api(url,options={}){let r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Something went wrong');return d}
function toast(s,error=false){let t=$('#toast');t.innerHTML=`<div class="toast ${error?'error':''}">${esc(s)}</div>`;setTimeout(()=>t.innerHTML='',3500)}
async function init(){try{if(location.pathname==='/reset'){resetPage();return}let me0=await api('/api/me');current=me0.user;if(me0.vip)vipInfo=me0.vip;if(location.pathname==='/admin'&&current&&current.role!=='admin'){home();toast('Administrator sign-in required',true);return}if(current)loggedNav();if(current?.role==='admin')admin();else if(current?.role==='provider')provider();else{home();if(location.pathname==='/admin'&&!current)openAuth('login')}}catch(e){home();if(location.pathname==='/admin')openAuth('login')}}
function loggedNav(){let nav=$('#nav');nav.innerHTML=current.role==='provider'?`<a href="#dashboard" onclick="openDashboard();return false">My profile</a><a href="#messages" onclick="showMessages()">Client messages</a>`:`${current.role==='admin'?`<a href="#dashboard" onclick="openDashboard();return false">Dashboard</a>`:''}${current.role==='customer'?'<a href="#discover" onclick="home();return false">Discover</a><a href="#vip" onclick="vipPage();return false">VIP</a><a href="#messages" onclick="showMessages()">Messages</a>':''}`;$('.nav-actions').innerHTML=`<span style="align-self:center;color:#aaa;font-size:12px">${esc(current.name)}</span>${current.role==='customer'?'<button class="button quiet" onclick="accountSettings()">Account</button>':''}<button class="button quiet" onclick="logout()">Log out</button>`}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'})}finally{current=null;location.reload()}}
function home(){if(current?.role==='provider'){provider();return}document.body.classList.remove('menu-open');$('#main').innerHTML=`<section class="hero vybe-hero"><div><div class="eyebrow">Meet people, find trusted local services</div><h1>Find your<br><span class="gradient">kind of vibe.</span></h1><p class="hero-copy">Discover independent local service providers, compare their menus and prices, and connect through your VYBE account.</p><div class="hero-buttons"><button class="button primary" onclick="document.querySelector('#directory').scrollIntoView({behavior:'smooth'})">Explore providers <span>↘</span></button><button class="button outline" onclick="openAuth('register','provider')">List your services</button><button class="button quiet" onclick="showVip()">Featured people ↓</button></div><div class="stats-strip"><div><strong>People first</strong><span>Independent providers</span></div><div><strong>Reviewed</strong><span>Profiles and feedback</span></div><div><strong>Private</strong><span>Customer accounts</span></div></div></div><div class="hero-visual"><div class="visual-glow"></div><div class="float-card"><div><small>VYBE COMMUNITY</small><strong>Find local talent.</strong></div><span class="live">SERVICES NEAR YOU</span></div></div></section><section class="directory" id="directory"><div class="section-head"><div><div class="eyebrow">Explore the directory</div><h2>Local providers, their services and prices</h2></div><span id="provider-count" style="color:var(--muted);font-size:12px">Loading approved profiles…</span></div><div class="filters"><input class="field search" id="query" placeholder="Search providers, services, or bio…" oninput="filterProfiles()"><select class="field" id="category" onchange="filterProfiles()"><option value="">All services</option></select><select class="field" id="location" onchange="filterProfiles()"><option value="">All locations</option></select></div><div class="grid people-grid" id="profile-grid"><div class="loading">Loading providers…</div></div></section><section class="directory vip-directory" id="vip-directory"><div class="section-head"><div><div class="eyebrow">VYBE VIP</div><h2>Featured providers</h2></div><span class="sub">Featured placement for approved providers. Access requires VIP membership.</span></div><div id="vip-grid" class="grid people-grid"></div></section><div class="footer-spacer"></div>`;loadProfiles()}
function showVip(){if(current?.role==='provider'){provider();return}if(!document.querySelector('#vip-directory'))home();document.querySelector('#vip-directory')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function loadProfiles(){try{siteConfig=await api('/api/config');profiles=await api('/api/profiles');$('#category').innerHTML='<option value="">All services</option>'+siteConfig.services.map(c=>`<option>${esc(c)}</option>`).join('');$('#location').innerHTML='<option value="">All locations</option>'+siteConfig.locations.map(c=>`<option>${esc(c)}</option>`).join('');filterProfiles()}catch(e){$('#profile-grid').innerHTML='<div class="empty">Providers are temporarily unavailable. Please try again.</div>'}}
function serviceModeLabel(mode){return ({in_call:'In-call',delivery:'Delivery',both:'In-call and delivery'})[mode]||'In-call and delivery'}
function serviceAmount(item){let value=item?.price;if(value===undefined||value===null||value==='')value=item?.price_min??0;return Math.max(0,Number(value)||0)}
function profileCard(x){let firstService=x.services?.[0],firstPrice=serviceAmount(firstService),price=firstService?`<span>${firstPrice>0?`UGX ${firstPrice.toLocaleString()}`:'Contact for pricing'}</span>`:'';let serviceChips=(x.services||[]).length?x.services.slice(0,3).map(c=>`<span class="chip">${esc(c.name)}</span>`).join(''):'<span class="chip muted-chip">Services being updated</span>';return `<article class="card person-card" onclick="openProfile(${x.id})"><div class="person-photo" style="background-image:url('${esc(x.photos?.[0]||'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=900')}')"><span class="tag">⌖ ${esc(x.location)}</span>${x.is_vip?'<span class="vip-badge">VYBE VIP</span>':''}${x.verified?'<span class="verified">✓ Verified</span>':''}</div><div class="card-body"><h3>${esc(x.display_name)}</h3><div class="rating-line">${x.rating_count?`★ ${Number(x.rating).toFixed(1)} <span>(${x.rating_count} reviews)</span>`:'New provider'}</div><p>${esc(x.bio)}</p><div class="chips">${serviceChips}</div><div class="person-footer">${price}<button class="mini">View services ↗</button></div></div></article>`}
function filterProfiles(){let q=($('#query')?.value||'').toLowerCase(),cat=$('#category')?.value||'',loc=$('#location')?.value||'';let matches=profiles.filter(x=>(!q||`${x.display_name||''} ${x.bio||''} ${(x.services||[]).map(s=>s.name).join(' ')}`.toLowerCase().includes(q))&&(!cat||(x.services||[]).some(s=>s.name===cat))&&(!loc||x.location===loc)),ordinary=matches.filter(x=>!x.is_vip),featured=matches.filter(x=>x.is_vip),counter=$('#provider-count');if(counter)counter.textContent=`${ordinary.length} profile${ordinary.length===1?'':'s'} available`;$('#profile-grid').innerHTML=ordinary.length?ordinary.map(profileCard).join(''):'<div class="empty">No providers match those filters yet. Try another search.</div>';let note=$('#vip-directory .section-head .sub');if(note)note.textContent=isVipMember()?'Featured profiles are open to VIP members.':'Reserved for active VYBE VIP members.';$('#vip-grid').innerHTML=isVipMember()?(featured.length?featured.map(profileCard).join(''):'<div class="empty">No featured providers are available yet.</div>'):'<div class="vip-lock"><h3>VIP membership required</h3><p>Featured providers are reserved for VYBE VIP members. Join VIP to browse premium profiles, save favourites and contact featured providers.</p><button class="button primary" onclick="vipPage()">See VIP membership <span>↗</span></button></div>'}
async function openProfile(id){try{let p=await api('/api/profiles/'+id);window._galleryPhotos=p.photos||[];window._galleryName=p.display_name;window._galleryIndex=0;if(current?.role==='customer')api('/api/saved').then(list=>{savedIds=new Set(list.map(x=>x.profile_id));let sb=$('#save-btn');if(sb)sb.textContent=savedIds.has(p.id)?'✓ Saved':'Save profile'}).catch(()=>{});history.pushState({profile:id},'',`#profile-${id}`);let videos=(p.videos||[]).map((src,i)=>`<video src="${esc(src)}" controls preload="metadata" aria-label="${esc(p.display_name)} video ${i+1}"></video>`).join('');let services=(p.services||[]).map(x=>{let amount=serviceAmount(x),price=amount?`UGX ${amount.toLocaleString()}`:'Contact for pricing';return `<div class="service-row public-service"><div><strong>${esc(x.name)}</strong><small>${price}</small></div></div>`}).join('');let reviews=(p.reviews||[]).map(r=>`<article class="review-card"><strong>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} <span>${esc(r.customer_name)}</span></strong><p>${esc(r.body||'Rated this provider')}</p><small>${esc(r.created_at)}</small></article>`).join('');let signedCustomer=current?.role==='customer'&&current.status==='active',canContact=signedCustomer&&(!p.is_vip||isVipMember()),phoneActions=canContact&&p.contact_phone?`<a class="button outline" href="tel:${encodeURIComponent(p.contact_phone)}">Call provider</a>`:'',whatsappActions=canContact&&p.contact_whatsapp?`<a class="button outline" target="_blank" rel="noopener" href="https://wa.me/${esc(p.contact_whatsapp.replace(/\D/g,''))}">WhatsApp ↗</a>`:'',contactActions=`<div class="contact-actions">${phoneActions}${whatsappActions}${canContact?`<button class="button primary" onclick="openMessageThread(${p.id})">Message on VYBE</button><button class="button outline" onclick="openReview(${p.id})">Leave a review</button>`:signedCustomer&&p.is_vip?'<p class="sub">VIP membership is required to contact or review this featured provider.</p>':!signedCustomer?'<button class="button primary" onclick="openAuth(&quot;login&quot;)">Sign in to see contact details</button>':''}${signedCustomer&&!phoneActions&&!whatsappActions?'<p class="sub contact-privacy-note">This provider has not added a phone or WhatsApp contact.</p>':''}</div>`;$('#main').innerHTML=`<section class="profile-page"><button class="button quiet back-button" onclick="home();history.pushState({},'','#discover')">← Back to directory</button><div class="profile-layout"><div><div class="profile-gallery">${(p.photos||[]).map((src,i)=>`<img src="${esc(src)}" alt="${esc(p.display_name)} profile photo ${i+1}" onclick="openLightbox(${i})" title="Tap to view photo">`).join('')}${(p.photos||[]).length>1?`<span class="gallery-count">${p.photos.length} photos · tap to view</span>`:''}</div>${videos?`<div class="profile-videos">${videos}</div>`:''}</div><div class="profile-info"><div class="eyebrow">${p.is_vip?'<span class="vip-badge">VYBE VIP</span>':'Local service provider'}</div><h1>${esc(p.display_name)} ${p.verified?'<span class="verified-inline">✓ Verified</span>':''}</h1><div class="profile-location">⌖ ${esc(p.location)}</div><div class="profile-location">Availability: ${esc(serviceModeLabel(p.service_mode))}</div><div class="rating-line big-rating">${p.rating_count?`★ ${Number(p.rating).toFixed(1)} <span>from ${p.rating_count} approved reviews</span>`:'New provider · no reviews yet'}</div><section class="profile-contact"><h2>Contact ${esc(p.display_name)}</h2>${contactActions}</section><h2>About</h2><p>${esc(p.bio)}</p><h2>Services & prices</h2><div class="public-services">${services||'<p class="sub">This provider has not added services yet.</p>'}</div><h2>Customer reviews</h2><div class="review-list">${reviews||'<p class="sub">No approved reviews yet.</p>'}</div>${current?.role==='customer'?`<div class="profile-actions">${(!p.is_vip||isVipMember())?`<button class="mini" id="save-btn" onclick="toggleSave(${p.id})">${savedIds.has(p.id)?'✓ Saved':'Save profile'}</button><button class="mini danger" onclick="reportProfile(${p.id})">Report this profile</button>`:'<p class="sub">VIP membership is required to save or report this featured profile.</p>'}</div>`:current?.role==='provider'?'<p class="sub">Sign in with a customer account to contact this provider.</p>':''}</div></div></section>`}catch(e){if(String(e.message||'').includes('VIP')){toast('VIP membership is required to view this profile',true);vipPage()}else{toast(e.message,true);home()}}}
function openLightbox(i){if(!(window._galleryPhotos||[]).length)return;window._galleryIndex=i;renderLightbox();document.body.style.overflow='hidden'}
function renderLightbox(){let ph=window._galleryPhotos||[],src=ph[window._galleryIndex];if(!src)return;let box=$('#lightbox');if(!box){document.body.insertAdjacentHTML('beforeend',`<div class="lightbox" id="lightbox" onclick="if(event.target===this)closeLightbox()"><button class="lightbox-close" aria-label="Close" onclick="closeLightbox()">×</button><button class="lightbox-prev" aria-label="Previous photo" onclick="stepLightbox(-1)">‹</button><img id="lightbox-img" alt="Profile photo"><button class="lightbox-next" aria-label="Next photo" onclick="stepLightbox(1)">›</button><div class="lightbox-caption" id="lightbox-caption"></div></div>`)}$('#lightbox-img').src=src;$('#lightbox-caption').textContent=`${window._galleryName||'Profile'} · photo ${window._galleryIndex+1} of ${ph.length}`;let multi=ph.length>1;$('.lightbox-prev').style.display=multi?'grid':'none';$('.lightbox-next').style.display=multi?'grid':'none'}
function stepLightbox(d){let ph=window._galleryPhotos||[];if(!ph.length)return;window._galleryIndex=(window._galleryIndex+d+ph.length)%ph.length;renderLightbox()}
function closeLightbox(){$('#lightbox')?.remove();document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(!$('#lightbox'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowRight')stepLightbox(1);if(e.key==='ArrowLeft')stepLightbox(-1)});
function openReview(id){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="review-modal"><section class="modal"><button class="close" onclick="$('#review-modal').remove()">×</button><h2>Rate this provider</h2><p class="sub">Reviews are checked by VYBE before publication. Keep it relevant to the listed service.</p><form class="form" onsubmit="submitReview(event,${id})"><label>Rating<select name="rating" required><option value="5">★★★★★ — Excellent</option><option value="4">★★★★☆ — Good</option><option value="3">★★★☆☆ — Fair</option><option value="2">★★☆☆☆ — Poor</option><option value="1">★☆☆☆☆ — Very poor</option></select></label><label>Review<textarea name="body" maxlength="1000" placeholder="Share useful feedback about the service"></textarea></label><button class="button primary">Submit for review</button></form></section></div>`)}
async function submitReview(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/reviews',{method:'POST',body:JSON.stringify({profile_id:id,rating:Number(d.rating),body:d.body})});$('#review-modal').remove();toast('Review sent for moderation')}catch(x){toast(x.message,true)}}
function showMessages(){if(!current||!['customer','provider'].includes(current.role))return toast('Sign in as a customer or provider to view messages',true);api('/api/messages').then(items=>{$('#main').innerHTML=`<section class="provider-layout"><div class="eyebrow">VYBE conversations</div><h1>Your <span class="gradient">messages.</span></h1><p class="sub">Private conversations between registered customers and providers.${current.role==='provider'?' You’ll only see customers who have contacted you.':''}</p><div class="inbox-list">${items.length?items.map(t=>`<button class="inbox-item" onclick="openMessageThread(${t.profile_id},${t.customer_id})"><strong>${esc(t.display_name)}</strong><span>${current.role==='provider'?`Customer: ${esc(t.customer_name)}`:'Provider conversation'}</span><small>${esc(t.body.slice(0,110))}</small></button>`).join(''):'<div class="empty">No conversations yet. Open an approved profile to start a message.</div>'}</div></section>`}).catch(e=>toast(e.message,true))}
async function openMessageThread(profileId,customerId=0){try{let d=await api('/api/messages?profile_id='+profileId);let peer=current.role==='provider'?customerId:0;$('#thread-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="thread-modal"><section class="modal thread-modal"><button class="close" onclick="$('#thread-modal').remove()">×</button><h2>${esc(d.profile)}</h2><p class="sub">Messages stay between your VYBE accounts.</p><div class="thread-list">${d.messages.map(m=>`<div class="message ${m.sender_id===current.id?'mine':''}"><small>${esc(m.sender_name)} · ${esc(m.created_at)}</small><p>${esc(m.body)}</p></div>`).join('')||'<div class="empty">Start the conversation with a friendly introduction.</div>'}</div><form class="form" onsubmit="sendMessage(event,${profileId},${peer})"><label>Message<textarea name="body" maxlength="2000" required placeholder="Write a message…"></textarea></label><button class="button primary">Send message</button></form></section></div>`)}catch(e){toast(e.message,true)}}
async function sendMessage(e,profileId,customerId){e.preventDefault();let body=new FormData(e.target).get('body');try{await api('/api/messages',{method:'POST',body:JSON.stringify({profile_id:profileId,customer_id:customerId,body})});await openMessageThread(profileId,customerId);toast('Message sent')}catch(x){toast(x.message,true)}}
window.addEventListener('popstate',()=>home());
function openAuth(mode='login',role='customer'){let rolePicker=mode==='register'?`<div class="row"><button class="mini ${role==='customer'?'ok':''}" onclick="setRole('customer')">Customer</button><button class="mini ${role==='provider'?'ok':''}" onclick="setRole('provider')">Profile owner</button></div>`:'';document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="$('#modal-back').remove()">×</button><h2 id="auth-title">${mode==='login'?'Welcome back':'Join the VYBE community'}</h2><p class="sub" id="auth-sub">${mode==='login'?'Sign in to continue to VYBE.':'Find your vibe with a free account.'}</p>${rolePicker}<form class="form" id="auth-form" onsubmit="submitAuth(event,'${mode}','${role}')"></form><p class="sub" style="margin:16px 0 0;text-align:center"><button class="switch" onclick="switchAuth('${mode}')">${mode==='login'?'Create an account':'Already have an account? Sign in'}</button></p></div></div>`);renderAuthForm(mode,role)}
function setRole(role){let mode=$('#auth-title').textContent.includes('Welcome')?'login':'register';$('#modal-back').remove();openAuth(mode,role)}
function switchAuth(mode){$('#modal-back').remove();openAuth(mode==='login'?'register':'login')}
function renderAuthForm(mode,role){let f=$('#auth-form');if(mode==='login'){f.innerHTML=`<label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="button primary" type="submit">Sign in</button>`;let sw=$('#auth-form')?.parentElement?.querySelector('.switch');if(sw&&!sw.previousElementSibling?.classList?.contains('forgot-line'))sw.insertAdjacentHTML('beforebegin',`<p class="sub forgot-line" style="margin:10px 0 0;text-align:center"><button class="switch" onclick="forgotPassword()">Forgot password?</button></p>`);return}f.innerHTML=`<label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Phone number (optional)<input name="phone" type="tel" autocomplete="tel"></label><label>Password<input name="password" type="password" minlength="6" maxlength="200" required autocomplete="new-password" oninput="pwHint(this,'customer')"></label><small class="pw-hint" id="pw-hint">Use at least 6 characters.</small><label>Confirm password<input name="passwordConfirm" type="password" minlength="6" maxlength="200" required autocomplete="new-password"></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" required style="width:auto"> I accept the platform terms and privacy policy</label><button class="button primary" type="submit">${role==='provider'?'Submit profile application':'Create account'}</button>`}
function pwHint(input,role){let el=$('#pw-hint');if(!el)return;let v=input.value,min=role==='admin'?12:6;if(!v){el.textContent=`Use at least ${min} characters.`;el.style.color='';return}let strong=v.length>=min;el.textContent=strong?'✓ Password is long enough.':`${min-v.length} more character(s) needed.`;el.style.color=strong?'#8be7f1':''}
async function submitAuth(e,mode,role){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{if(mode==='login'){let r=await api('/api/login',{method:'POST',body:JSON.stringify(d)});if(r.mfa_required){openMfa(r.mfa_token);return}$('#modal-back')?.remove();await init();toast('Welcome back.')}else{d.role=role;let r=await api('/api/register',{method:'POST',body:JSON.stringify(d)});$('#modal-back')?.remove();toast(r.message);if(role==='customer')openAuth('login');}}catch(x){toast(x.message,true)}}
function openMfa(token){$('#modal-back')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back"><div class="modal"><h2>Two-factor verification</h2><p class="sub">Enter the 6-digit code from your authenticator app to finish signing in.</p><form class="form" onsubmit="submitMfa(event)"><input type="hidden" name="mfa_token" value="${esc(token)}"><label>Verification code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code" autofocus></label><button class="button primary">Verify & sign in</button></form></div></div>`)}
async function submitMfa(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/login/mfa',{method:'POST',body:JSON.stringify(d)});$('#modal-back')?.remove();await init();toast('Signed in.')}catch(x){toast(x.message,true)}}
function forgotPassword(){$('#modal-back')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="$('#modal-back').remove()">×</button><h2>Forgot your password?</h2><p class="sub">Enter your registered email and we'll send password-reset instructions if an account exists.</p><form class="form" onsubmit="submitForgot(event)"><label>Email address<input name="email" type="email" required autocomplete="email"></label><button class="button primary">Send reset instructions</button></form></div></div>`)}
async function submitForgot(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{let r=await api('/api/password/forgot',{method:'POST',body:JSON.stringify(d)});$('#modal-back')?.remove();toast(r.message||'If an account with that email exists, you will receive password-reset instructions.');if(r.dev_reset_link)setTimeout(()=>{if(confirm('Development mode: open the reset link now?'))location.href=r.dev_reset_link},300)}catch(x){toast(x.message,true)}}
function resetPage(){let token=new URLSearchParams(location.search).get('token')||'';home();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back"><div class="modal"><h2>Set a new password</h2><p class="sub">Choose a strong password you haven't used before. This link works once.</p><form class="form" onsubmit="submitReset(event)"><input type="hidden" name="token" value="${esc(token)}"><label>New password<input name="password" type="password" minlength="8" required autocomplete="new-password" oninput="pwHint(this,'customer')"></label><small class="pw-hint" id="pw-hint">Use 8+ characters mixing lower case, UPPER CASE, numbers and symbols.</small><label>Confirm new password<input name="passwordConfirm" type="password" minlength="8" required autocomplete="new-password"></label><button class="button primary">Update password</button></form></div></div>`)}
async function submitReset(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.password!==d.passwordConfirm)return toast('Passwords do not match',true);try{let r=await api('/api/password/reset',{method:'POST',body:JSON.stringify({token:d.token,password:d.password,passwordConfirm:d.passwordConfirm})});$('#modal-back')?.remove();history.replaceState({},'', '/');toast(r.message||'Password updated. Sign in with your new password.');openAuth('login')}catch(x){toast(x.message,true)}}
function openDashboard(){if(current?.role==='admin')admin();else provider()}
const labels={overview:'Overview',applications:'Applications',admins:'Admin team',providers:'Providers',customers:'Customers',vip:'VIP management',profiles:'Profile reviews',reviews:'Customer reviews',catalog:'Services & locations',reports:'Reports & moderation',audit:'Audit trail',settings:'Settings'};
const labelIcons={overview:'◫',applications:'▧',admins:'⚇',providers:'♙',customers:'♧',vip:'♛',profiles:'♡',reports:'⚑',audit:'◷',settings:'⚙',reviews:'★',catalog:'☷'};
async function admin(){let data=await api('/api/stats').catch(()=>null);if(!data){home();toast('Administrator sign-in required',true);return}$('#main').innerHTML=`<div class="dashboard"><aside class="side"><div class="side-label">WORKSPACE</div>${Object.entries(labels).filter(([k])=>k!=='admins'||current?.is_super).map(([k,v])=>`<button class="${tab===k?'active':''}" onclick="showAdmin('${k}')"><span>${labelIcons[k]}</span>${v}</button>`).join('')}<div class="side-label" style="margin-top:auto;padding-top:35px">VYBE · ADMIN</div></aside><section class="dash-main" id="admin-content"></section></div>`;if(tab==='overview')renderOverview(data);else showAdmin(tab)}
function renderOverview(s){$('#admin-content').innerHTML=`<div class="dash-top"><div><h1>Good evening, ${esc(current.name.split(' ')[0])}</h1><p>Here’s what’s happening across VYBE today.</p></div><button class="button primary" onclick="showAdmin('applications')">Review applications ↗</button></div><div class="dash-cards">${[['Registered users','users'],['Customers','customers'],['Profile owners','providers'],['Pending applications','pending_applications'],['Active profile owners','active_providers'],['Profiles awaiting review','unpublished_profiles'],['Approved profiles','approved_profiles'],['Open reports','open_reports'],['Reviews pending','pending_reviews'],['VIP profiles','vip_profiles']].map(([n,k])=>`<div class="metric"><span>${n}<em>↗</em></span><strong>${s[k]}</strong></div>`).join('')}</div><div class="panel"><div class="panel-title"><h2>Quick actions</h2></div><div style="padding:18px;display:flex;gap:10px;flex-wrap:wrap">${[['applications','Review applications'],['profiles','Review profiles'],['reviews','Moderate reviews'],['catalog','Edit services & locations'],['reports','Review reports']].map(([k,v])=>`<button class="button outline" onclick="showAdmin('${k}')">${v} →</button>`).join('')}</div></div><div class="panel" id="admin-activity"><div class="panel-title"><h2>Recent account activity</h2><button class="mini" onclick="showAdmin('audit')">View activity log</button></div><p class="sub" style="padding:16px">Loading recent administrator actions…</p></div>`;api('/api/admin/audit').then(a=>{let box=$('#admin-activity');if(box)box.innerHTML=`<div class="panel-title"><h2>Recent account activity</h2><button class="mini" onclick="showAdmin('audit')">View activity log</button></div>${a.slice(0,5).map(x=>`<p class="activity-row"><strong>${esc(x.admin_name||'Admin')}</strong> ${esc(x.action)} ${esc(x.target_type)} #${esc(x.target_id)} <small>${esc(x.created_at)}</small></p>`).join('')||'<p class="sub" style="padding:16px">No administrator activity recorded yet.</p>'}`}).catch(()=>{});}
async function showAdmin(key){if(!current||current.role!=='admin'){home();toast('Administrator sign-in required',true);return}tab=key;let data=await api('/api/stats').catch(()=>null);if(!data){home();toast('Administrator sign-in required',true);return}$('#main').innerHTML=`<div class="dashboard"><aside class="side"><div class="side-label">WORKSPACE</div>${Object.entries(labels).filter(([k])=>k!=='admins'||current?.is_super).map(([k,v])=>`<button class="${key===k?'active':''}" onclick="showAdmin('${k}')">${labelIcons[k]}　${v}</button>`).join('')}<div class="side-label" style="padding-top:30px">VYBE · ADMIN</div></aside><section class="dash-main" id="admin-content"><div class="loading">Loading workspace…</div></section></div>`;if(key==='overview'){renderOverview(data||{});return}let result=await api('/api/admin/'+key).catch(()=>[]);adminCache[key]=result;let content=$('#admin-content');let title=labels[key];content.innerHTML=`<div class="dash-top"><div><h1>${title}</h1><p>${key==='admins'?'Create and manage administrator accounts.':`Review and manage ${key==='audit'?'recent administrator activity':`your ${key} queue`}.`}</p></div>${key==='settings'?'<button class="button primary" onclick="saveSettings()">Save settings</button>':''}${key==='admins'&&current.is_super?'<button class="button primary" onclick="createAdmin()">Create admin account</button>':''}</div>${key==='admins'?tableAdmins(result):key==='applications'?tableApplications(result):key==='providers'?tableProviders(result):key==='customers'?tableCustomers(result):key==='profiles'?tableProfiles(result):key==='reports'?tableReports(result):key==='audit'?tableAudit(result):key==='reviews'?tableReviews(result):key==='vip'?vipAdminPanel(result):key==='catalog'?catalogForm(result):settingsForm()}`}
function panel(title,headers,rowsHtml){return `<div class="panel"><div class="panel-title"><h2>${title}</h2><span class="badge">${headers.count??''} records</span></div><div class="table-wrap"><table><thead><tr>${headers.cols.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rowsHtml||`<tr><td colspan="${headers.cols.length}" style="text-align:center;color:#888">Nothing here yet.</td></tr>`}</tbody></table></div></div>`}
function badge(s){let c=['approved_active','active','approved','resolved'].includes(s)?'green':['pending_review','awaiting_payment','payment_verification','pending','open','expired'].includes(s)?'yellow':['rejected','suspended','unpublished'].includes(s)?'red':'';return `<span class="badge ${c}">${esc((s||'').replaceAll('_',' '))}</span>`}
function tableApplications(a){return panel('Provider applications — approve account access',{cols:['Applicant','Location','Applied','Application & account','Admin actions'],count:a.length},a.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.email)} · ${esc(x.phone)}</small></td><td>${esc(x.location)}</td><td>${esc(x.created_at?.slice(0,10))}</td><td>${badge(x.status)}</td><td><div class="actions"><a class="mini" href="mailto:${encodeURIComponent(x.email)}">Contact</a><button class="mini ok" onclick="appStatus(${x.id},'approved')">${x.profile_id?'Approve &amp; publish':'Approve provider'}</button><button class="mini danger" onclick="appStatus(${x.id},'rejected')">Reject</button></div></td></tr>`).join(''))}
function tableProviders(a){return panel('Provider accounts — profile visibility and account controls',{cols:['Provider','Location','Account','Profile','VIP','Admin controls'],count:a.length},a.map(x=>{let canFeature=x.status==='active'&&x.profile_status==='approved';return `<tr><td><b>${esc(x.name)}</b><small>${esc(x.email)}</small></td><td>${esc(x.location||'—')}</td><td>${badge(x.status)}</td><td>${badge(x.profile_status||'not submitted')}</td><td>${x.is_vip?'<span class="vip-badge">VYBE VIP</span>':'—'}</td><td><div class="actions">${x.status==='active'?`<button class="mini" onclick="setUser(${x.id},'inactive')">Deactivate</button>`:`<button class="mini ok" onclick="setUser(${x.id},'active')">${x.status==='suspended'?'Reactivate':'Activate'}</button>`}${x.status==='suspended'?'':`<button class="mini danger" onclick="setUser(${x.id},'suspended')">Suspend</button>`}${x.is_vip?`<button class="mini" onclick="setVip(${x.id},false)">Remove VIP</button>`:canFeature?`<button class="mini" onclick="setVip(${x.id},true)">Move to VIP</button>`:'—'}<button class="mini danger" onclick="deleteAccount(${x.id},'provider')">Delete</button></div></td></tr>`}).join(''))}
function tableAdmins(a){return panel('Administrator accounts — overall admin manages this team',{cols:['Admin','Email','Role','Status','Controls'],count:a.length},a.map(x=>`<tr><td><b>${esc(x.name)}</b><small>joined ${esc(String(x.created_at||'').slice(0,10))}</small></td><td>${esc(x.email)}</td><td>${x.is_owner?'<span class="vip-badge">Protected owner</span>':x.is_super?'<span class="vip-badge">Overall admin</span>':'Admin'}</td><td>${badge(x.status)}</td><td><div class="actions">${x.is_owner?'<span class="sub">Protected owner account</span>':x.id!==current.id?`<button class="mini" onclick="editAdmin(${x.id})">Edit</button><button class="mini" onclick="resetAdmin(${x.id})">Reset password</button>${x.is_super?`<button class="mini" onclick="setAdminSuper(${x.id},false)">Remove overall access</button>`:`<button class="mini gold" onclick="setAdminSuper(${x.id},true)">Make overall admin</button>`}${x.status==='active'?`<button class="mini" onclick="setAdminStatus(${x.id},'suspended')">Suspend</button>`:`<button class="mini ok" onclick="setAdminStatus(${x.id},'active')">Reactivate</button>`}<button class="mini danger" onclick="deleteAdmin(${x.id})">Delete</button>`:'<span class="sub">This is your account</span>'}</div></td></tr>`).join(''))}
function createAdmin(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="$('#modal-back').remove()">×</button><h2>Create administrator</h2><p class="sub">New admins can review applications, edit profiles, moderate reviews and manage VIP. Overall admins can also manage other admin accounts. Passwords need at least 12 characters and a mix of character types.</p><form class="form" onsubmit="submitAdmin(event)"><label>Full name<input name="name" required maxlength="100"></label><label>Email address<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="12" required></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="is_super" style="width:auto"> Overall admin — can manage other admins</label><button class="button primary">Create admin account</button></form></div></div>`)}
async function submitAdmin(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.is_super=d.is_super==='on';try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(d)});$('#modal-back')?.remove();toast('Administrator account created');showAdmin('admins')}catch(x){toast(x.message,true)}}
async function editAdmin(id){let x=(adminCache.admins||[]).find(a=>a.id===id)||{};let name=prompt('Administrator name:',x.name||'');if(name===null)return;let email=prompt('Administrator email:',x.email||'');if(email===null)return;await mutate(`/api/admin/admin/${id}`,{action:'details',name,email},'Administrator details updated')}
async function resetAdmin(id){let password=prompt('New administrator password (at least 12 characters with a mix of character types):');if(!password)return;await mutate(`/api/admin/admin/${id}`,{action:'password',password},'Administrator password updated')}
async function setAdminSuper(id,is_super){await mutate(`/api/admin/admin/${id}`,{action:'super',is_super},is_super?'Overall-admin access granted':'Overall-admin access removed')}
async function setAdminStatus(id,status){await mutate(`/api/admin/admin/${id}`,{action:'status',status},'Administrator account status updated')}
async function deleteAdmin(id){if(!confirm('Delete this administrator account? They will no longer be able to sign in.'))return;await mutate(`/api/admin/admin/${id}`,{action:'status',status:'deleted'},'Administrator account deleted')}
function tableCustomers(a){return panel('Customer accounts — activate, manage VIP access, suspend or delete',{cols:['Customer','Contact','Status','VIP access','Joined','Account controls'],count:a.length},a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}<small>${esc(x.phone)}</small></td><td>${badge(x.status)}</td><td>${x.is_vip?`<span class="vip-badge">VIP client</span><small>until ${esc(String(x.vip_expires||'—').slice(0,16))}</small>`:'Standard'}</td><td>${esc(x.created_at?.slice(0,10))}</td><td><div class="actions">${x.status==='active'?`<button class="mini" onclick="setUser(${x.id},'inactive')">Deactivate</button>`:`<button class="mini ok" onclick="setUser(${x.id},'active')">${x.status==='suspended'?'Reactivate':'Activate'}</button>`}${x.status==='suspended'?'':`<button class="mini danger" onclick="setUser(${x.id},'suspended')">Suspend</button>`}${x.is_vip?`<button class="mini" onclick="setCustomerVip(${x.id},false)">Remove VIP</button>`:`<button class="mini ok" onclick="setCustomerVip(${x.id},true)">Grant VIP</button>`}<button class="mini danger" onclick="deleteAccount(${x.id},'customer')">Delete</button></div></td></tr>`).join(''))}
function tableProfiles(a){return panel('Individual profiles — approve and publish to customers',{cols:['Person & media','Location & interests','State','Moderation'],count:a.length},a.map(x=>{let photos=JSON.parse(x.photos||'[]'),videos=JSON.parse(x.videos||'[]');return `<tr><td><b>${esc(x.display_name)}</b><small>${esc(x.account_name)} · ${esc(x.email)} · ${esc(x.provider_phone)}</small><small>${esc(x.bio)}</small><div class="admin-media">${photos.map(src=>`<img class="listing-image" src="${esc(src)}" alt="Profile image">`).join('')}${videos.map((src,i)=>`<video src="${esc(src)}" controls preload="metadata" aria-label="Profile video ${i+1}"></video>`).join('')}</div></td><td>${esc(x.location)}<small>${esc(JSON.parse(x.categories||'[]').join(', '))}</small></td><td>${badge(x.status)} ${x.verified?'<span class="verified-inline">✓ Verified</span>':''}</td><td><div class="actions"><button class="mini ok" onclick="profileDecision(${x.id},'approved')">Approve &amp; publish</button><button class="mini" onclick="profileDecision(${x.id},'changes_requested')">Request edits</button><button class="mini danger" onclick="profileDecision(${x.id},'rejected')">Reject</button><button class="mini danger" onclick="profileDecision(${x.id},'unpublished')">Unpublish</button></div></td></tr>`}).join(''))}
function tableReviews(a){return panel('Customer reviews awaiting moderation',{cols:['Provider','Customer','Rating','Review','State','Actions'],count:a.length},a.map(x=>`<tr><td>${esc(x.display_name)}</td><td>${esc(x.customer_name)}</td><td>${'★'.repeat(x.rating)} (${x.rating}/5)</td><td>${esc(x.body)}</td><td>${badge(x.status)}</td><td><button class="mini ok" onclick="reviewDecision(${x.id},'approved')">Approve</button> <button class="mini danger" onclick="reviewDecision(${x.id},'rejected')">Reject</button></td></tr>`).join(''))}
function catalogForm(c){return `<section class="panel catalog-editor"><h2>Services & locations</h2><p class="sub">Edit the menus shown on provider profiles.</p><h3>Services</h3><div id="admin-service-items" class="catalog-items">${(c.services||[]).map(v=>catalogItem('service',v)).join('')}</div><button type="button" class="mini" onclick="addCatalogItem('service')">+ Add service</button><h3>Available locations</h3><div id="admin-location-items" class="catalog-items">${(c.locations||[]).map(v=>catalogItem('location',v)).join('')}</div><button type="button" class="mini" onclick="addCatalogItem('location')">+ Add location</button><button class="button primary" onclick="saveCatalog()">Save changes</button></section>`}
function tableReports(a){return panel('Community reports',{cols:['Reporter','Profile','Reason','Status','Actions'],count:a.length},a.map(x=>`<tr><td>${esc(x.reporter)}</td><td>${esc(x.profile_name||'Unknown profile')}</td><td>${esc(x.reason)}</td><td>${badge(x.status)}</td><td><button class="mini ok" onclick="reportStatus(${x.id},'resolved')">Resolve</button> <button class="mini" onclick="reportStatus(${x.id},'escalated')">Escalate</button></td></tr>`).join(''))}
function tableAudit(a){return panel('Recent administrative actions',{cols:['Admin','Action','Target','Details','Time'],count:a.length},a.map(x=>`<tr><td>${esc(x.admin_name||x.admin_id)}</td><td>${esc(x.action)}</td><td>${esc(x.target_type)} #${esc(x.target_id)}</td><td>${esc(x.details)}</td><td>${esc(x.created_at)}</td></tr>`).join(''))}
function settingsForm(){return `<div class="panel" style="padding:22px"><h2>Platform settings</h2><p style="color:#999;font-size:13px">Update VYBE platform details.</p><div class="form" style="max-width:520px"><label>Platform name<input id="setting-name" value="VYBE"></label><label>Contact email<input id="setting-email" type="email" value="hello@vybe.test"></label><label>VIP price (UGX)<input id="setting-vip-price" value="150000"></label><label>VIP duration (days)<input id="setting-vip-days" value="30"></label></div></div>`}
async function appStatus(id,status){let notes=status==='rejected'?prompt('Private administrator note:','')||'':'';await mutate(`/api/admin/application/${id}`,{status,notes},status==='approved'?'Provider approved; any submitted profile is now published and the dashboard is ready.':'Application updated')}
async function profileDecision(id,status){let feedback=['rejected','changes_requested'].includes(status)?prompt('Profile feedback for the owner:','Please update your profile details.')||'':'';let verified=status==='approved'&&confirm('Mark this profile as verified?');await mutate(`/api/admin/profile/${id}`,{status,feedback,verified},status==='approved'?'Profile approved and published publicly':'Profile review saved')}
async function reviewDecision(id,status){await mutate(`/api/admin/review/${id}`,{status},'Review moderation saved')}
async function setVip(id,is_vip){await mutate(`/api/admin/provider/${id}`,{is_vip},is_vip?'Provider moved into VIP':'Provider removed from VIP')}
async function setCustomerVip(id,is_vip){await mutate(`/api/admin/customer/${id}`,{is_vip},is_vip?'Customer granted VIP access':'Customer VIP access removed')}
function catalogItem(kind,value=''){let type=kind==='service'?'service':'location';return `<div class="catalog-item"><input class="field catalog-${type}" maxlength="160" value="${esc(value)}" placeholder="Enter ${type} name"><button class="mini danger" type="button" onclick="this.parentElement.remove()">Remove</button></div>`}
function addCatalogItem(kind){let box=$('#admin-'+(kind==='service'?'service':'location')+'-items');if(box)box.insertAdjacentHTML('beforeend',catalogItem(kind))}
async function saveCatalog(){let services=[...document.querySelectorAll('.catalog-service')].map(x=>x.value.trim()).filter(Boolean),locations=[...document.querySelectorAll('.catalog-location')].map(x=>x.value.trim()).filter(Boolean),data={services,locations};try{await api('/api/admin/catalog',{method:'POST',body:JSON.stringify(data)});toast('Menu changes saved');showAdmin('catalog')}catch(e){toast(e.message,true)}}
async function setUser(id,status){await mutate(`/api/admin/user/${id}`,{status},'Account status updated')}
async function deleteAccount(id,role){if(!confirm(`Delete this ${role} account?${role==='provider'?' Their profile will be removed from the public directory.':''} They will no longer be able to sign in.`))return;await mutate(`/api/admin/user/${id}`,{status:'deleted'},`${role==='provider'?'Provider and public profile':'Customer'} account deleted`)}
async function reportStatus(id,status){await mutate(`/api/admin/report/${id}`,{status},'Report updated')}
async function saveSettings(){for(let [key,value] of [['platform_name',$('#setting-name').value],['contact_email',$('#setting-email').value],['vip_price_ugx',$('#setting-vip-price').value],['vip_duration_days',$('#setting-vip-days').value]])await api('/api/admin/settings',{method:'POST',body:JSON.stringify({key,value})});toast('Settings saved')}
async function mutate(url,data,msg){try{await api(url,{method:'POST',body:JSON.stringify(data)});toast(msg);showAdmin(tab)}catch(e){toast(e.message,true)}}
let draftPhotos=[];
function renderDraftPhotos(){let box=$('#photo-preview');if(box)box.innerHTML=draftPhotos.map((src,i)=>`<span class="photo-slot"><img src="${esc(src)}" alt="Profile photo ${i+1}"><button type="button" aria-label="Remove photo" onclick="removeDraftPhoto(${i})">×</button></span>`).join('')}
function removeDraftPhoto(i){draftPhotos.splice(i,1);renderDraftPhotos()}
function providerVipPanel(p){if(p?.is_vip)return '<section class="panel"><h2>VIP placement</h2><p class="sub">Your profile is featured in VYBE VIP.</p></section>';let message=encodeURIComponent(`Hello, I would like to request VIP placement for my VYBE profile: ${p?.display_name||current.name}.`);return `<section class="panel"><h2>VIP placement</h2><p class="sub">Contact the VYBE administrator to request VIP placement for your profile.</p><a class="button outline" href="https://wa.me/256747757933?text=${message}" target="_blank" rel="noopener">Request VIP placement ↗</a></section>`}
async function provider(){let d=await api('/api/provider').catch(()=>null);if(!d){$('#main').innerHTML='<section class="panel"><h2>Provider dashboard unavailable</h2><p class="sub">Please sign in again to access your profile and client messages.</p></section>';return}let p=d.profile,active=!['suspended','deleted','rejected','expired'].includes(current.status);draftPhotos=p?.photos||[];draftVideos=p?.videos||[];$('#main').innerHTML=`<div class="provider-layout"><div class="eyebrow">Your VYBE space</div><h1>Welcome, <span class="gradient">${esc(current.name.split(' ')[0])}.</span></h1><p style="color:var(--muted)">Manage your community profile.</p><div class="notice">Account ${badge(current.status)}　Profile ${badge(p?.status||'not created')}${p?.feedback?`<br>Moderator feedback: ${esc(p.feedback)}`:''}</div><div class="split"><div class="panel"><h2>Profile performance</h2><div class="rating-line big-rating">${d.rating?.count?`★ ${Number(d.rating.rating).toFixed(1)} <span>from ${d.rating.count} approved reviews</span>`:'No approved customer ratings yet'}</div><p class="sub">${p?.status==='approved'?'Your profile is published. Edits return it to review until approved.':'Your profile stays private while it awaits review.'}</p>${p?.verified?'<span class="verified-inline">✓ Verified by VYBE</span>':''}<p>${p?.is_vip?'<span class="vip-badge">VYBE VIP</span>':'<span class="sub">Not in VIP</span>'}</p><div class="owner-reviews"><h3>Customer feedback</h3>${(d.reviews||[]).length?d.reviews.map(r=>`<article class="review-card"><strong>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} <span>${esc(r.customer_name)}</span></strong><p>${esc(r.body||'Rated your profile')}</p><small>${badge(r.status)} · ${esc(r.created_at)}</small></article>`).join(''):'<p class="sub">Reviews submitted to your profile appear here.</p>'}</div></div></div>${active?`<section class="panel profile-editor"><h2>${p?'Edit your profile':'Create your profile'}</h2><p class="sub">Use only photos and videos you own or have permission to share. You can edit and submit while your profile is pending; it appears to customers after admin approval.</p><form class="form" onsubmit="submitProfile(event)"><label>Display name<input name="display_name" maxlength="80" value="${esc(p?.display_name||current.name)}" required></label><label>General location<select name="location" required><option value="">Choose a location</option>${d.config.locations.map(loc=>`<option value="${esc(loc)}" ${p?.location===loc||(!p&&d.application?.location===loc)?'selected':''}>${esc(loc)}</option>`).join('')}</select></label><label>Service availability<select name="service_mode" required><option value="in_call" ${p?.service_mode==='in_call'?'selected':''}>In-call</option><option value="delivery" ${p?.service_mode==='delivery'?'selected':''}>Delivery</option><option value="both" ${(!p?.service_mode||p?.service_mode==='both')?'selected':''}>In-call and delivery</option></select></label><label>About me<textarea name="bio" maxlength="1200" required placeholder="Tell customers about your experience and the services you provide">${esc(p?.bio||d.application?.description||'')}</textarea></label><label>Categories (comma separated)<input name="categories" value="${esc((p?.categories||[]).join(', '))}" placeholder="Music, art, outdoors" required></label><section class="service-editor"><div><h3>Service menu & pricing</h3><p class="sub">Choose services from the menu and set one standard price in UGX.</p></div><div id="provider-services">${serviceRows(p?.services||[],d.config.services)}</div><button class="mini" type="button" onclick="addServiceRow()">+ Add a service</button></section><div class="row"><label>Contact phone<input name="contact_phone" value="${esc(p?.contact_phone||'')}" placeholder="Optional"></label><label>WhatsApp<input name="contact_whatsapp" value="${esc(p?.contact_whatsapp||'')}" placeholder="Optional"></label></div><p class="sub">Your phone and WhatsApp details are shown only to signed-in customers.</p><label>Photos (up to 10; PNG, JPEG or WebP; max 5 MB each)<input id="profile-files" type="file" multiple accept="image/png,image/jpeg,image/webp" onchange="previewProfilePhotos(event)"></label><div id="photo-preview" class="photo-preview">${draftPhotos.map((src,i)=>`<span class="photo-slot"><img src="${esc(src)}" alt="Profile photo ${i+1}"><button type="button" aria-label="Remove photo" onclick="removeDraftPhoto(${i})">×</button></span>`).join('')}</div><label>Videos (up to 2; MP4, WebM or MOV; max 20 MB each)<input id="video-files" type="file" multiple accept="video/mp4,video/webm,video/quicktime" onchange="previewProfileVideos(event)"></label><div id="video-preview" class="photo-preview">${draftVideos.map((src,i)=>`<span class="photo-slot"><video src="${esc(src)}" controls></video><button type="button" aria-label="Remove video" onclick="removeDraftVideo(${i})">×</button></span>`).join('')}</div><label class="checkline"><input type="checkbox" name="image_consent"> I own these images/videos or have consent to publish them</label><button class="button primary" type="submit">Submit profile for review</button></form></section>`:`<div class="panel"><h2>Profile access</h2><p class="sub">Your dashboard is ready while your provider application or profile is under review. An administrator must approve your profile before customers can see it.</p></div>`}</div>`;$('#main').insertAdjacentHTML('afterbegin',providerVipPanel(p))}
function serviceRows(selected,catalog){let items=(selected||[]).filter(x=>x&&x.name);if(!items.length)items=[{name:'',price:0}];return items.map(x=>serviceRow(x,catalog)).join('')}
function serviceRow(item,catalog){return `<div class="service-row service-edit-row"><select class="field service-name" aria-label="Service name"><option value="">Choose service</option>${catalog.map(n=>`<option value="${esc(n)}" ${item.name===n?'selected':''}>${esc(n)}</option>`).join('')}</select><input class="field service-price" type="number" min="0" step="1000" placeholder="Price in UGX" aria-label="Price in UGX" value="${esc(serviceAmount(item)||'')}"><button class="mini danger" type="button" onclick="this.parentElement.remove()">Remove</button></div>`}
function addServiceRow(){let box=$('#provider-services');if(!box)return;if(box.children.length>=20)return toast('Choose up to 20 services',true);api('/api/config').then(c=>box.insertAdjacentHTML('beforeend',serviceRow({},c.services))).catch(e=>toast(e.message,true))}
function collectServices(){return [...document.querySelectorAll('#provider-services .service-edit-row')].filter(row=>row.querySelector('.service-name').value).map(row=>({name:row.querySelector('.service-name').value,price:Number(row.querySelector('.service-price').value||0)}))}
function previewProfilePhotos(e){let files=[...e.target.files];if(draftPhotos.length+files.length>10){e.target.value='';return toast('You can add up to 10 profile photos',true)}if(files.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5*1024*1024)){e.target.value='';return toast('Use PNG, JPEG or WebP images up to 5 MB each',true)}document.querySelectorAll('#photo-preview .new-photo').forEach(x=>x.remove());files.forEach(f=>{let img=document.createElement('img');img.className='new-photo';img.alt='New profile photo preview';img.src=URL.createObjectURL(f);$('#photo-preview').append(img)})}
function previewProfileVideos(e){let files=[...e.target.files];if(draftVideos.length+files.length>2){e.target.value='';return toast('You can add up to 2 videos',true)}if(files.some(f=>!['video/mp4','video/webm','video/quicktime'].includes(f.type)||f.size>20*1024*1024)){e.target.value='';return toast('Use MP4, WebM or MOV videos up to 20 MB each',true)}files.forEach(f=>{let v=document.createElement('video');v.className='new-video';v.controls=true;v.src=URL.createObjectURL(f);$('#video-preview').append(v)})}
function removeDraftVideo(i){draftVideos.splice(i,1);let box=$('#video-preview');if(box)box.innerHTML=draftVideos.map((src,j)=>`<span class="photo-slot"><video src="${esc(src)}" controls></video><button type="button" aria-label="Remove video" onclick="removeDraftVideo(${j})">×</button></span>`).join('')}
async function fileData(f){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('File could not be read'));r.readAsDataURL(f)})}
async function submitProfile(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.categories=d.categories.split(',').map(s=>s.trim()).filter(Boolean);d.services=collectServices();d.photos=[...draftPhotos];d.videos=[...draftVideos];try{for(let f of $('#profile-files').files)d.photos.push(await fileData(f));for(let f of $('#video-files').files)d.videos.push(await fileData(f));await api('/api/provider/profile',{method:'POST',body:JSON.stringify(d)});toast('Profile submitted for administrator review');provider()}catch(x){toast(x.message,true)}}
async function reportProfile(id){let reason=prompt('What should VYBE moderators review about this profile?');if(!reason)return;try{await api('/api/report',{method:'POST',body:JSON.stringify({profile_id:id,reason})});toast('Report sent to moderators')}catch(e){toast(e.message,true)}}
async function accountSettings(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal-back" onclick="if(event.target===this)this.remove()"><div class="modal"><button class="close" onclick="$('#modal-back').remove()">×</button><h2>Account settings</h2><p class="sub">Your account details remain private.</p><form class="form" onsubmit="saveAccount(event)"><label>Name<input name="name" value="${esc(current.name)}" required maxlength="100"></label><label>Phone<input name="phone" value="${esc(current.phone||'')}"></label><button class="button outline" type="button" onclick="$('#password-fields').hidden=false">Change password</button><div id="password-fields" hidden><label>Current password<input name="currentPassword" type="password" autocomplete="current-password"></label><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" oninput="pwHint(this,${JSON.stringify(current.role||'customer')})"></label><small class="pw-hint" id="pw-hint">Use 8+ characters mixing lower case, UPPER CASE, numbers and symbols.</small></div><button class="button primary">Save changes</button></form><hr style="border-color:#ffffff14;margin:18px 0"><h2 style="font-size:17px">Security</h2><p class="sub">Sign out of every device, including this one.</p><button class="button outline" type="button" onclick="logoutAll()">Sign out everywhere</button>${current.role==='admin'?`<div id="mfa-box" class="sub" style="margin-top:14px">Loading two-factor status…</div>`:''}</div></div>`);if(current.role==='admin')loadMfa()}
async function loadMfa(){let box=$('#mfa-box');if(!box)return;let me=(await api('/api/me').catch(()=>null))?.user;let on=!!me?.totp_enabled;box.innerHTML=on?`<p><span class="badge active">Two-factor ON</span> Your administrator account requires a verification code at sign-in.</p><div class="row"><input class="field" id="mfa-code" placeholder="6-digit code" maxlength="6" inputmode="numeric"><button class="mini danger" onclick="mfaAction('disable')">Turn off</button></div>`:`<p><span class="badge">Two-factor OFF</span> Protect your administrator account with an authenticator app.</p><button class="mini ok" onclick="mfaAction('setup')">Set up two-factor</button>`}
async function mfaAction(action){try{if(action==='setup'){let pw=prompt('Confirm your account password to start two-factor setup:');if(pw===null)return;let r=await api('/api/account/mfa/setup',{method:'POST',body:JSON.stringify({password:pw})});document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="mfa-modal"><section class="modal"><button class="close" onclick="$('#mfa-modal').remove()">×</button><h2>Set up authenticator</h2><p class="sub">Add this secret to Google Authenticator, Authy or similar, then enter the 6-digit code to confirm.</p><p style="font:600 18px 'Space Grotesk';letter-spacing:.18em;word-break:break-all;background:#0d0d15;border:1px solid #353342;border-radius:10px;padding:12px">${esc(r.secret)}</p><form class="form" onsubmit="mfaEnable(event)"><label>Verification code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button class="button primary">Activate two-factor</button></form></section></div>`);return}if(action==='disable'){let pw=prompt('Confirm your account password:');if(pw===null)return;let code=prompt('Enter your current 6-digit code:');if(code===null)return;let r=await api('/api/account/mfa/disable',{method:'POST',body:JSON.stringify({password:pw,code})});toast(r.message||'Two-factor turned off.');loadMfa()}}catch(x){toast(x.message,true)}}
async function mfaEnable(e){e.preventDefault();let code=new FormData(e.target).get('code');try{let r=await api('/api/account/mfa/enable',{method:'POST',body:JSON.stringify({code})});$('#mfa-modal')?.remove();toast(r.message||'Two-factor activated.');loadMfa()}catch(x){toast(x.message,true)}}
async function logoutAll(){try{await api('/api/account/logout-all',{method:'POST',body:'{}'});current=null;location.reload()}catch(x){toast(x.message,true)}}
async function saveAccount(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/account/profile',{method:'POST',body:JSON.stringify({name:d.name,phone:d.phone})});if(d.password){await api('/api/account/password',{method:'POST',body:JSON.stringify({currentPassword:d.currentPassword,password:d.password})})}current=(await api('/api/me')).user;loggedNav();$('#modal-back').remove();toast('Account updated')}catch(x){toast(x.message,true)}}
function isVipMember(){return vipInfo?.status==='active'||current?.role==='admin'}
const vipPills={none:['vip-standard','STANDARD'],pending:['vip-pending','VIP request pending'],active:['vip-active','VIP ACTIVE'],expired:['vip-expired','VIP expired'],suspended:['vip-suspended','VIP suspended']};
function vipHero(){return `<div class="vip-hero"><div class="eyebrow">VYBE membership</div><h1>VIP</h1><p>Unlock featured providers, premium profiles and direct contact with VYBE's featured community. Membership is activated by the administrator and stays active until its expiry date.</p></div>`}
function vipStatusCard(cfg){let st=vipInfo?.status||'none',exp=vipInfo?.expires_at?String(vipInfo.expires_at).slice(0,16):'',price=Number(cfg?.vip?.price||0),days=cfg?.vip?.days||30,pill=vipPills[st]||vipPills.none;let copy={none:'You are browsing as a STANDARD member. VIP membership unlocks featured VIP-only profiles, private saved favourites and direct contact with featured providers.',pending:'Your VIP request is waiting for administrator approval. Access begins as soon as the membership is activated.',active:`Your VIP membership is active${exp?` until ${exp}`:''}. You have full access to featured providers and VIP contact.`,expired:`Your VIP membership expired${exp?` on ${exp}`:''}. Renew to regain access to featured profiles and premium contact.`,suspended:'Your VIP membership is suspended. Contact the VYBE administrator to resolve this.'}[st];let action=st==='active'?`<span class="sub">${exp?'Expires '+exp:'Active'}</span>`:st==='pending'?'<span class="sub">Awaiting administrator approval</span>':!current?`<button class="button primary" onclick="openAuth(&quot;login&quot;)">Sign in to join VIP <span>↗</span></button>`:current.role!=='customer'?'<span class="sub">VIP membership is available to customer accounts.</span>':`<button class="button primary" onclick="vipRequest()">${st==='expired'?'Renew VIP membership':'Request VIP membership'} <span>↗</span></button>${price?`<span class="sub">UGX ${price.toLocaleString()} · ${days} days</span>`:''}`;return `<div class="vip-status"><span class="status-pill ${pill[0]}">${pill[1]}</span><p class="sub" style="flex:1;min-width:230px;margin:0">${copy}</p><div class="vip-status-action">${action}</div></div>`}
function vipBenefits(){return `<div class="vip-benefits"><div class="vip-benefit standard"><h3>STANDARD</h3><ul><li>Browse standard approved profiles</li><li>Contact standard providers</li><li>Moderated reviews and reports</li></ul></div><div class="vip-benefit premium"><h3>VIP ♛</h3><ul><li>Everything in Standard</li><li>Access VIP-only featured profiles</li><li>Dedicated VIP directory section</li><li>Save VIP profiles privately</li><li>Contact featured providers directly</li></ul></div></div>`}
function vipCard(p){return `<article class="card vip-card" onclick="openProfile(${p.id})"><div class="person-photo vip-photo" style="background-image:url('${esc(p.photos?.[0]||'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=900')}')"><span class="tag">⌖ ${esc(p.location)}</span><span class="vip-badge gold">♛ VIP</span>${p.verified?'<span class="verified">✓ Verified</span>':''}</div><div class="card-body"><h3>${esc(p.display_name)}</h3><div class="rating-line">${p.rating_count?`★ ${Number(p.rating).toFixed(1)} <span>(${p.rating_count} reviews)</span>`:'New provider'}</div><p>${esc(p.bio)}</p><div class="person-footer"><span class="vip-gold">Featured provider</span><span class="sub">${(p.photos||[]).length||1} photo${(p.photos||[]).length===1?'':'s'}</span><button class="mini gold" onclick="event.stopPropagation();openProfile(${p.id})">View profile ↗</button></div></div></article>`}
function savedCard(x){return `<article class="card vip-card" onclick="openProfile(${x.profile_id})"><div class="person-photo vip-photo" style="background-image:url('${esc((x.photos||[])[0]||'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=900')}')"><span class="tag">⌖ ${esc(x.location)}</span>${x.is_vip?'<span class="vip-badge gold">♛ VIP</span>':''}</div><div class="card-body"><h3>${esc(x.display_name)}</h3><div class="rating-line">${x.rating_count?`★ ${Number(x.rating).toFixed(1)} <span>(${x.rating_count} reviews)</span>`:'New provider'}</div><p>${esc(x.bio||'')}</p><div class="person-footer"><span class="sub">Saved ${esc(String(x.created_at||'').slice(0,10))}</span><button class="mini gold" onclick="event.stopPropagation();openProfile(${x.profile_id})">View profile ↗</button></div></div></article>`}
async function vipPage(){if(current?.role==='provider'){provider();return}if(current?.role==='admin'){admin();return}document.body.classList.remove('menu-open');try{let cfg=await api('/api/config');if(current){let me=await api('/api/me');current=me.user;if(me.vip)vipInfo=me.vip}let saved=[],vips=[];if(current?.role==='customer'){vipInfo=(await api('/api/vip')).membership||vipInfo;saved=await api('/api/saved').catch(()=>[]);savedIds=new Set(saved.map(x=>x.profile_id))}if(isVipMember()){let all=await api('/api/profiles').catch(()=>[]);vips=all.filter(x=>x.is_vip)}let body='';if(vips.length){body+=`<div class="section-head" style="margin-top:34px"><div><div class="eyebrow">Featured providers</div><h2>Premium profiles</h2></div><span class="sub">${vips.length} VIP profile${vips.length===1?'':'s'}</span></div><div class="vip-grid">${vips.map(vipCard).join('')}</div>`}else if(isVipMember()){body+='<div class="vip-lock" style="margin-top:30px"><h3>No featured profiles yet</h3><p>New VIP providers appear here once the administrator grants them featured placement.</p></div>'}else{body+=`<div class="vip-lock" style="margin-top:30px"><h3>VIP-only profiles are private</h3><p>Featured providers are reserved for active VIP members. ${current?'Request VIP membership':'Join VYBE as a customer'} to browse premium profiles, save favourites and contact featured providers directly.</p>${current?`<button class="button primary" onclick="vipRequest()">Request VIP membership <span>↗</span></button>`:`<button class="button primary" onclick="openAuth(&quot;register&quot;,'customer')">Create a customer account <span>↗</span></button>`}</div>`}if(current?.role==='customer'){body+=`<div class="vip-saved"><div class="section-head"><div><div class="eyebrow">Your private list</div><h2>Saved profiles</h2></div><span class="sub">Only you can see these</span></div>${saved.length?`<div class="vip-grid">${saved.filter(x=>!x.is_vip||isVipMember()).map(savedCard).join('')}</div>`:'<div class="empty">You have not saved any profiles yet. Use the Save button on any profile you like.</div>'}</div>`}$('#main').innerHTML=`<section class="vip-page">${vipHero()}${vipStatusCard(cfg)}${body}${vipBenefits()}</section>`}catch(e){toast(e.message,true)}}
async function vipRequest(){if(!current||current.role!=='customer')return toast('Sign in with a customer account to request VIP membership',true);try{await api('/api/vip/request',{method:'POST',body:'{}'});toast('VIP request sent — the administrator will activate your membership');vipPage()}catch(e){toast(e.message,true)}}
async function toggleSave(id){if(!current||current.role!=='customer')return toast('Sign in with a customer account to save profiles',true);try{let r=await api('/api/saved',{method:'POST',body:JSON.stringify({profile_id:id})});savedIds=r.saved?new Set([...savedIds,id]):new Set([...savedIds].filter(x=>x!==id));toast(r.saved?'Profile saved to your private list':'Profile removed from saved');let sb=$('#save-btn');if(sb)sb.textContent=r.saved?'✓ Saved':'Save profile'}catch(e){if(String(e.message||'').includes('VIP')){toast(e.message,true);vipPage()}else toast(e.message,true)}}
function vipBadge(s){let c=s==='active'?'gold':s==='pending'?'yellow':'red';return `<span class="badge ${c}">${esc(s||'—')}</span>`}
function vipAdminPanel(d){let profs=d.profiles||[],members=d.members||[],hist=d.history||[];return `<div class="panel"><div class="panel-title"><h2>VIP profiles — featured placement</h2><span class="badge">${profs.filter(x=>x.is_vip).length} featured</span></div><div class="table-wrap"><table><thead><tr><th>Provider</th><th>Location</th><th>Account</th><th>Placement</th><th>Actions</th></tr></thead><tbody>${profs.map(x=>`<tr><td><b>${esc(x.display_name)}</b><small>${esc(x.account_name)} · ${esc(x.email)}</small><small>${esc(x.bio||'')}</small></td><td>${esc(x.location)}</td><td>${badge(x.status)}</td><td>${x.is_vip?'<span class="vip-badge gold">♛ VIP featured</span>':'Standard'}</td><td><div class="actions">${x.is_vip?`<button class="mini danger" onclick="setVip(${x.id},false)">Remove VIP</button>`:`<button class="mini gold" onclick="setVip(${x.id},true)">Make VIP</button>`}</div></td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center;color:#888">No approved providers yet.</td></tr>'}</tbody></table></div><p class="sub" style="padding:12px">Removing VIP instantly returns the profile to the standard approved directory.</p></div><div class="panel"><div class="panel-title"><h2>VIP members</h2><span class="badge">${members.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Status</th><th>Started</th><th>Expires</th><th>Actions</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${esc(m.name)}</b><small>${esc(m.email)}</small></td><td>${vipBadge(m.status)}</td><td>${esc(String(m.started_at||'—').slice(0,16))}</td><td>${esc(m.expires_at?String(m.expires_at).slice(0,16):'—')}</td><td><div class="actions">${m.status!=='active'?`<button class="mini ok" onclick="vipMember(${m.user_id},'activate')">Activate</button><button class="mini gold" onclick="vipMember(${m.user_id},'renew')">Renew</button>`:''}${m.status==='active'?`<button class="mini" onclick="vipMember(${m.user_id},'suspend')">Suspend</button><button class="mini gold" onclick="vipSetExpiry(${m.user_id})">Set expiry</button><button class="mini danger" onclick="vipMember(${m.user_id},'expire')">Expire now</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center;color:#888">No VIP membership records yet. Customers can request VIP from the VIP page.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-title"><h2>Membership history</h2><span class="badge">${hist.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Action</th><th>Status</th><th>Expiry</th><th>By</th><th>Time</th></tr></thead><tbody>${hist.map(h=>`<tr><td>${esc(h.member_name||'—')}</td><td>${esc(h.action)}</td><td>${vipBadge(h.status)}</td><td>${esc(h.expires_at?String(h.expires_at).slice(0,16):'—')}</td><td>${esc(h.admin_name||'System')}</td><td>${esc(String(h.created_at||'').slice(0,16))}</td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center;color:#888">No membership history yet.</td></tr>'}</tbody></table></div></div>`}
function vipMember(userId,action){let days=null;if(['activate','renew','setexpiry'].includes(action)){let v=prompt('VIP membership duration in days','30');if(v===null)return;days=Math.max(1,Math.min(3650,parseInt(v,10)||30))}api('/api/admin/vipmember',{method:'POST',body:JSON.stringify({user_id:userId,action,days})}).then(r=>{toast(r.expires_at?'Membership updated until '+String(r.expires_at).slice(0,16):'Membership updated');showAdmin('vip')}).catch(e=>toast(e.message,true))}
function vipSetExpiry(userId){vipMember(userId,'setexpiry')}
init();
